from collections import defaultdict
from typing import Dict, List, Tuple, Set, Optional
import heapq

def find(parent: List[int], node: int) -> int:
    """Find the root of the node"""
    if parent[node] == node:
        return node
    return find(parent, parent[node])

def union(parent: List[int], rank: List[int], node1: int, node2: int) -> None:
    """Union two sets using rank to keep the tree flat"""
    root1 = find(parent, node1)
    root2 = find(parent, node2)
    if root1 != root2:
        if rank[root1] < rank[root2]:
            parent[root1] = root2
        elif rank[root1] > rank[root2]:
            parent[root2] = root1
        else:
            parent[root2] = root1
            rank[root1] += 1

def kruskal_mst(graph: Dict[int, List[Tuple[int, int]]]) -> Dict[int, List[Tuple[int, int]]]:
    """Return the Minimum Spanning Tree (MST) using Kruskal's algorithm"""
    n = len(graph)
    parent = list(range(n))
    rank = [0] * n
    mst = defaultdict(list)

    # Add all edges from the graph to a priority queue
    edges = []
    for node in graph:
        for neighbor, weight in graph[node]:
            edges.append((weight, node, neighbor))

    # Sort edges by weight
    heapq.heapify(edges)

    while edges:
        weight, node1, node2 = heapq.heappop(edges)
        if find(parent, node1) != find(parent, node2):
            union(parent, rank, node1, node2)
            mst[node1].append((node2, weight))
            mst[node2].append((node1, weight))

    return mst

def shortest_path(graph: Dict[int, List[Tuple[int, int]]], source: int, target: int) -> Tuple[float, List[int]]:
    """Find the shortest path from source to target using the MST"""
    if source == target:
        return (0.0, [source])

    mst = kruskal_mst(graph)

    # Use BFS to find the shortest path in the MST
    visited = set()
    queue = [(0, [source])]
    while queue:
        distance, path = queue.pop(0)
        current = path[-1]
        if current == target:
            return (distance, path)
        if current in visited:
            continue
        visited.add(current)
        for neighbor, weight in mst[current]:
            if neighbor not in visited:
                queue.append((distance + weight, path + [neighbor]))

    return (float("inf"), None)

