from collections import defaultdict
from heapq import heappop, heappush
from math import inf

def shortest_path(graph, source, target):
    # Kruskal's Minimum Spanning Tree Algorithm
    def find(parent, i):
        if parent[i] == i:
            return i
        return find(parent, parent[i])

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

    parent = {}
    rank = {}

    # Create disjoint sets
    for node in graph:
        parent[node] = node
        rank[node] = 0

    # Initialize MST with minimum spanning tree edges
    min_heap = []
    for node in graph:
        for neighbor, weight in graph[node]:
            edge = (weight, node, neighbor)
            heappush(min_heap, edge)

    # Create a MST
    mst = set()
    while min_heap and (find(parent, source) != find(parent, target)):
        weight, u, v = heappop(min_heap)
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst.add((u, v))

    # If no MST found, source and target are not connected
    if (find(parent, source) != find(parent, target)):
        return inf, None

    # Reconstruct the path
    path = []
    def path_reconstruction(parent, node):
        if node in parent:
            path_reconstruction(parent, parent[node])
            path.append(node)

    path_reconstruction(parent, source)
    return sum(weight for weight, _, _ in min_heap), path[::-1]

