import heapq

def astar_search(graph, heuristic, source, target):
    # Initialize priority queue with the source node
    priority_queue = []
    heapq.heappush(priority_queue, (0, source))
    # Initialize dictionary to store cost, parent nodes, and the path
    came_from = {}
    cost_so_far = {}
    came_from[source] = None
    cost_so_far[source] = 0

    while priority_queue:
        # Get the node with the lowest cost
        current_cost, current_node = heapq.heappop(priority_queue)

        if current_node == target:
            break

        for next_node, edge_weight in graph[current_node]:
            new_cost = cost_so_far[current_node] + edge_weight

            if next_node not in cost_so_far or new_cost < cost_so_far[next_node]:
                cost_so_far[next_node] = new_cost
                priority = new_cost + heuristic(next_node, target)
                heapq.heappush(priority_queue, (priority, next_node))
                came_from[next_node] = current_node

    # If there is no path, return infinity and None
    if target not in cost_so_far:
        return float("inf"), None
    # Reconstruct the path
    path = []
    current_node = target
    while current_node is not None:
        path.append(current_node)
        current_node = came_from[current_node]
    # The path is backwards, so we reverse it
    path.reverse()
    return cost_so_far[target], path

def heuristic(node, target):
    # Manhattan Distance
    return abs(node[0] - target[0]) + abs(node[1] - target[1])

def shortest_path(graph, source, target):
    # Assume graph nodes are tuples like (x, y)
    # Example: graph = {(1, 2): [(2, 3), (3, 4)], (2, 3): [(1, 2), (4, 1)], (3, 4): [(2, 3)]}
    return astar_search(graph, heuristic, source, target)

