import heapq
from collections import defaultdict
from math import inf

def shortest_path(graph, source, target):
    # Step 1: Relabel nodes to remove negative weights
    def reweight_graph(graph):
        G = defaultdict(dict)
        for node, neighbors in graph.items():
            for neighbor, weight in neighbors:
                # If the weight is negative, it's added directly
                if weight < 0:
                    G[node][neighbor] = weight
                # If the weight is non-negative, it's doubled
                else:
                    G[node][neighbor] = 2 * weight
        return G

    # Step 2: Use Dijkstra's Algorithm to find the shortest path
    def dijkstra(graph, source):
        distances = {node: inf for node in graph}
        distances[source] = 0
        queue = [(0, source)]

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node].items():
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        return distances

    graph = reweight_graph(graph)
    distances = dijkstra(graph, source)

    # Step 3: Use Bellman-Ford to handle negative weights in the relabeled graph
    def bellman_ford(graph, source, target):
        distances = {node: inf for node in graph}
        distances[source] = 0
        for _ in range(len(graph) - 1):
            for node, neighbors in graph.items():
                for neighbor, weight in neighbors.items():
                    if distances[node] + weight < distances[neighbor]:
                        distances[neighbor] = distances[node] + weight

        return distances[target] != inf, distances

    can_reach, distances_with_relabel = bellman_ford(graph, source, target)
    if not can_reach:
        return float("inf"), None

    # Step 4: Reconstruct the shortest path
    path = []
    current_node = target
    while current_node != source:
        for neighbor, weight in graph[current_node].items():
            if distances_with_relabel[current_node] == distances_with_relabel[neighbor] + weight:
                path.append(neighbor)
                current_node = neighbor
                break
    path.append(source)
    path.reverse()

    return distances_with_relabel[target], path

