```python
def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def kruskal(graph, source, target):
    # Create a disjoint set for each node
    parent = {}
    rank = {}
    for node in graph:
        parent[node] = node
        rank[node] = 0

    # Sort edges based on weight
    edges = []
    for node in graph:
        for neighbor, weight in graph[node]:
            edges.append((weight, node, neighbor))
    edges.sort()

    # Union-Find structure to maintain the connected components
    parent = {node: node for node in graph}
    rank = {node: 0 for node in graph}

    # Initialize the MST
    MST = []
    distance = float("inf")
    path = None

    for weight, node, neighbor in edges:
        if find(parent, node) != find(parent, neighbor):
            union(parent, rank, node, neighbor)
            MST.append((node, neighbor, weight))

    # Check if the target is reachable from the source
    if find(parent, source) == find(parent, target):
        distance = min(d for _, _, d in MST if (source, target) in MST)
        path = [source]
        current = target
        while current != source:
            for neighbor, weight in graph[current]:
                if (current, neighbor, weight) in MST and find(parent, neighbor) == find(parent, current):
                    path.append(neighbor)
                    current = neighbor
                    break
        path.reverse()

    return distance, path

