```python
import heapq
from collections import deque

def shortest_path(graph, source, target):
    # Initialize distances and predecessor arrays
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    predecessors = {node: None for node in graph}

    # Queue for SPFA
    queue = deque([source])

    # SPFA (Shortest Path Faster Algorithm)
    while queue:
        current = queue.popleft()
        for neighbour, weight in graph[current]:
            distance_through_current = distances[current] + weight
            if distance_through_current < distances[neighbour]:
                distances[neighbour] = distance_through_current
                predecessors[neighbour] = current
                if neighbour not in distances:
                    queue.append(neighbour)

    # Bellman-Ford to handle negative weight cycles
    for node in graph:
        for neighbour, weight in graph[node]:
            if distances[node] + weight < distances[neighbour]:
                return float('inf'), None

    # Reconstruct the path using predecessors
    if distances[target] == float('inf'):
        return float('inf'), None
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = predecessors[current]

    # Since the path is constructed backwards, reverse it
    return distances[target], path[::-1]

