from typing import Dict, List, Tuple
import heapq

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if self.rank[rootX] > self.rank[rootY]:
                self.parent[rootY] = rootX
            elif self.rank[rootX] < self.rank[rootY]:
                self.parent[rootX] = rootY
            else:
                self.parent[rootY] = rootX
                self.rank[rootX] += 1

def kruskal(graph):
    n = len(graph)
    mst = {i: float('inf') for i in range(n)}  # Distance to the tree
    mst[0] = 0  # Distance from source to itself is 0
    mst[1] = float('inf') if 1 in graph else 0  # Distance from source to target if target is not reachable, otherwise 0
    parent = [i for i in range(n)]
    edges = sorted((w, u, v) for u in graph for v, w in graph[u])
    for w, u, v in edges:
        if mst[u] + w < mst[v]:
            mst[v] = mst[u] + w
            if parent[v] != v:
                mst[parent[v]] = min(mst[parent[v]], mst[v])
            parent[v] = u
            if v == 1:
                return mst[1]
    return mst[1]

def shortest_path(graph, source, target):
    n = len(graph)
    uf = UnionFind(n)
    mst = {i: float('inf') for i in range(n)}
    mst[source] = 0
    mst[target] = float('inf') if target not in graph else 0
    for u in graph:
        for w, v in graph[u]:
            if uf.find(u) != uf.find(v):
                uf.union(u, v)
                mst[v] = min(mst[v], mst[u] + w)
                if v == target:
                    return mst[v], [source] + [v for v in uf.parent if uf.find(v) == target][:-1]
    return float('inf'), None

