from collections import defaultdict
from typing import Dict, List, Tuple
import heapq

def shortest_path(graph: Dict[str, List[Tuple[str, int]]], source: str, target: str) -> Tuple[float, List[str]]:
    def find(parent: Dict[str, str], node: str) -> str:
        if parent[node] == node:
            return node
        parent[node] = find(parent, parent[node])
        return parent[node]

    def union(parent: Dict[str, str], rank: Dict[str, int], node1: str, node2: str):
        root1 = find(parent, node1)
        root2 = find(parent, node2)
        if root1 != root2:
            if rank[root1] > rank[root2]:
                parent[root2] = root1
            elif rank[root1] < rank[root2]:
                parent[root1] = root2
            else:
                parent[root2] = root1
                rank[root1] += 1

