        mst = []
        for weight, node, neighbor in edges:
            if find(parent, node) != find(parent, neighbor):
                mst.append((node, neighbor, weight))
                union(parent, rank, node, neighbor)
        return mst, parent, rank

    def find_path(parent: Dict[str, str], nodes: List[str]) -> List[str]:
        path = []
        for node in nodes:
            path.append(node)
            parent_node = parent[node]
            while parent_node != node:
                path.append(parent_node)
                parent_node = parent[parent_node]
        return path

    mst, parent, rank = kruskal(graph)
    visited = {source}
    distance = float('inf')
    path = []
    for weight, node1, node2 in mst:
        if node1 == source and node2 == target:
            distance = weight
            path = [source, target]
            break
        elif node1 == source or node2 == source:
            visited.add(node1)
            visited.add(node2)
            weight_sum = weight
            path = find_path(parent, [node1, node2])
            if target in visited:
                distance = weight_sum
                path = [source] + path[1:]
                break
    if target not in visited:
        return float('inf'), None
    return distance, path
