        # Forward search iteration
        if len(queue_forward) > len(queue_backward):
            queue, visited, distances, queue_next, visited_next = queue_backward, visited_backward, min_distance_backward, queue_forward, visited_forward
        else:
            queue, visited, distances, queue_next, visited_next = queue_forward, visited_forward, min_distance_forward, queue_backward, visited_backward

        # Dequeue the front node
        node = queue.pop(0)
        distance = distances[node]

        # Check if we have reached the target
        if node == target:
            # Reconstruct the path from source to target
            path = [target]
            while path[-1] != source:
                path.append(queue_next.pop(0))
            path.reverse()
