def bidirectional_search(graph, source, target):
    # Breadth-First Search (BFS) from the source
    def bfs(graph, start, end):
        queue = deque([(start, [])])
        visited = {start}
        while queue:
            node, path = queue.popleft()
            if node == end:
                return path + [node]
            for neighbor, _ in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [node]))
        return None

    # Bidirectional BFS
    start_bfs = bfs(graph, source, target)
    end_bfs = bfs(graph, target, source)

    # If the BFS explores to the same node in opposite directions, we have found the shortest path
    while start_bfs and end_bfs and start_bfs[-1] == end_bfs[-1]:
        path = start_bfs
        path.reverse()  # Reverse the path to get the correct direction
        return (len(path) - 1, path)

    # If the BFS does not converge, the target is unreachable
    return (float("inf"), None)

