def shortest_path(graph, source, target):
    # Yen's Algorithm to find K shortest loopless Steiner trees
    def dijkstra(graph, source, target):
        distances = {node: inf for node in graph}
        distances[source] = 0
        queue = [(0, source)]
        while queue:
            current_distance, current_node = heappop(queue)
            if current_node == target:
                return current_distance
            if current_distance > distances[current_node]:
                continue
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heappush(queue, (distance, neighbor))
        return inf

    def yen_k_shortest_paths(graph, source, target, k):
        shortest_paths = [dijkstra(graph, source, target)]
        for _ in range(k - 1):
            previous_paths = shortest_paths[-1]
            for node in previous_paths:
                if previous_paths[node] == inf:
                    continue
                for predecessor, _ in graph[node]:
                    if previous_paths[predecessor] == inf:
                        continue
                    new_path = previous_paths[predecessor] + graph[predecessor][node]
                    if new_path < previous_paths[node]:
                        previous_paths[node] = new_path
            shortest_paths.append(previous_paths)
        return shortest_paths

