    # 2. Transform the original graph
    for node, edges in graph.items():
        for neighbor, weight in edges:
            graph[node][neighbor] += distances[neighbor] - distances[node]

    # 3. Run Dijkstra from source to target
    distances = dijkstra(graph, source)

