    distances = bellman_ford(graph, source)

    if distances[target] == float('inf'):
        return float('inf'), None

    # Re-run Dijkstra's algorithm to find the shortest path
    distances = dijkstra(graph, target)
    return distances[target], [target] if distances[target] != float('inf') else None

