            (cost, u, path) = heappop(pq)
            if u not in visited:
                visited.add(u)
                path.append(u)
                if u == end:
                    return path, cost
                for v in graph[u]:
                    if v not in visited:
                        heappush(pq, (cost + graph[u][v], v, path[:]))
        return None, float('inf')

    # Preprocess the graph to remove negative weights
    preprocessed_graph = preprocess(graph)

    # Find the shortest path from source to target
    path, cost = dijkstra(preprocessed_graph, source, target, max(preprocessed_graph.keys()) + 1)

    if path is None:
        return float('inf'), None
    else:
        return cost, path

