from collections import defaultdict
import heapq

def shortest_path(graph, source, target):
    # Convert the undirected graph to a directed graph
    directed_graph = defaultdict(list)
    for node, neighbors in graph.items():
        for neighbor, weight in neighbors:
            directed_graph[node].append((neighbor, weight))
            directed_graph[neighbor].append((node, weight))

    # Initialize the residual capacities and distances
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    path_distance = {node: float("inf") for node in graph}
    path_distance[source] = 0

    # Initialize the residual capacities
    residual_graph = {node: defaultdict(lambda: float("inf")) for node in graph}
    for node, neighbors in directed_graph.items():
        for neighbor, weight in neighbors:
            residual_graph[node][neighbor] = weight

    # Perform the Ford-Fulkerson algorithm
    while True:
        # Find the shortest path using BFS
        distances_bf = {node: float("inf") for node in graph}
        distances_bf[source] = 0
        distances_bf[target] = float("inf")

        queue = [(0, source)]
        while queue:
            min_distance, current_node = heapq.heappop(queue)
            if min_distance < distances_bf[current_node]:
                for neighbor, capacity in residual_graph[current_node].items():
                    if capacities[current_node][neighbor] > 0 and min_distance + capacities[current_node][neighbor] == distances_bf[neighbor]:
                        distances_bf[neighbor] = min_distance + capacities[current_node][neighbor]
                        heapq.heappush(queue, (distances_bf[neighbor], neighbor))

        # If there is no path from source to target
        if distances_bf[target] == float("inf"):
            return (float("inf"), None)

        # Find the bottleneck capacity
        bottleneck_capacity = min(capacities[node][neighbor] for node, neighbor in path_distance.items())

        # Augment the flow along the path
        for node, neighbor in path_distance.items():
            residual_graph[node][neighbor] -= bottleneck_capacity
            residual_graph[neighbor][node] += bottleneck_capacity

        path_distance[target] = 0
        path = [target]
        current_node = target
        while current_node != source:
            for neighbor, capacity in residual_graph[current_node].items():
                if capacity > 0 and path_distance[neighbor] > path_distance[current_node] + capacities[current_node][neighbor]:
                    path_distance[neighbor] = path_distance[current_node] + capacities[current_node][neighbor]
                    current_node = neighbor
                    path.append(current_node)
        path.reverse()

        return (path_distance[target], path)

