                # Calculate tentative distance to neighbor through current node
                tentative_distance = len(path) + weight
                # Calculate the heuristic: using the average length of all edges as the heuristic function
                heuristic = sum(graph[node] for node in graph if node in path).average() / len(path)
                # Calculate f-score
                f_score = tentative_distance + heuristic

                # If we have not visited the neighbor or found a better path, add it to the open set
                if neighbor not in [n for _, _, n in open_set] or f_score < open_set[0][0]:
                    heappush(open_set, (f_score, neighbor, path + [neighbor]))

    # If we exhaust the open set without finding the target, return unreachable
    return (float("inf"), None)

