def shortest_path(graph, source, target):
    from collections import deque, defaultdict
    from heapq import heappop, heappush
    import sys

    if source not in graph or target not in graph:
        return float("inf"), None

    # Function to get neighboring nodes and the corresponding edge weight
    def get_neighbors(node):
        return [(neighbor, weight) for neighbor, weight in graph[node]]

    # Bi-directional BFS
    def bi_directional_bfs():
        # Initialize the sets of visited nodes for both directions
        visited_start, visited_end = set(), set()
        # Initialize the queues for the BFS
        queue_start, queue_end = deque([(source, 0)]), deque([(target, 0)])

        while queue_start and queue_end:
            # Start BFS
            node_start, distance_start = heappop(queue_start)
            if node_start not in visited_start:
                visited_start.add(node_start)
                if node_start == target:
                    return distance_start
                # Add unvisited neighbors to the queue
                for neighbor, weight in get_neighbors(node_start):
                    if neighbor not in visited_start:
                        heappush(queue_start, (neighbor, distance_start + weight))

            # End BFS
            node_end, distance_end = heappop(queue_end)
            if node_end not in visited_end:
                visited_end.add(node_end)
                if node_end == source:
                    return distance_end
                # Add unvisited neighbors to the queue
                for neighbor, weight in get_neighbors(node_end):
                    if neighbor not in visited_end:
                        heappush(queue_end, (neighbor, distance_end + weight))
        return float("inf"), None

    # Call the bi-directional BFS to find the shortest path
    distance, path = bi_directional_bfs()
    if distance == float("inf"):
        return distance, None
    else:
        # Reconstruct the path
        path = []
        while source != target:
            for neighbor, weight in get_neighbors(source):
                if source != target and path and path[-1] == neighbor:
                    path.append(source)
                    source = neighbor
                    break
        path.append(target)
        path.reverse()
        return distance, path

