```python
from collections import defaultdict, deque

def shortest_path(graph, source, target):
    # Create a dictionary to keep track of the previous node in the path
    previous = {node: None for node in graph}
    # Initialize the queue for BFS and the distance dictionary
    queue = deque([(source, 0)])
    # Initialize the distance dictionary to store the distance to each node
    distance = {node: float('inf') for node in graph}
    distance[source] = 0

    while queue:
        current_node, current_distance = queue.popleft()
        # If we reach the target node, we know the path is valid and can be processed
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = previous[current_node]
            return (current_distance, path[::-1])

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            if distance[neighbor] > current_distance + weight:
                distance[neighbor] = current_distance + weight
                previous[neighbor] = current_node
                queue.append((neighbor, distance[neighbor]))

    # If the target node is not reachable
    return (float('inf'), None)

